document.addEventListener("DOMContentLoaded",function(){console.log("Inicializando sistema de FAQs...");const e=document.querySelectorAll(".faq-item");console.log("FAQs encontradas:",e.length),0!==e.length?(e.forEach((o,n)=>{const t=o.querySelector(".faq-question");t?t.addEventListener("click",function(){const t=o.classList.contains("active");e.forEach(e=>{e!==o&&e.classList.contains("active")&&e.classList.remove("active")}),t?o.classList.remove("active"):o.classList.add("active"),console.log(`FAQ #${n+1} - ${t?"cerrado":"abierto"}`)}):console.warn(`FAQ #${n+1} no tiene un elemento .faq-question`)}),console.log("Sistema de FAQs inicializado correctamente")):console.log("No se encontraron elementos FAQ en la página - Script FAQ finalizando")});